function solve(input) {
  const { height } = input;
  let left = 0, right = height.length - 1;
  let maxArea = 0;
  while (left < right) {
    const w = right - left;
    const h = Math.min(height[left], height[right]);
    maxArea = Math.max(maxArea, w * h);
    if (height[left] < height[right]) left++;
    else right--;
  }
  return maxArea;
}
